$user=mg_require_admin_page_any(['admin.blog.view','admin.blog.manage']);if(!mg_admin_permission_user_has($user,'admin.blog.manage')){mg_admin_page_forbidden('admin.blog.manage');}$pdo=mg_db();$schema=mg_blog_schema_ready($pdo);$postId=max(0,(int)($_GET['id']??$_POST['id']??0));$errors=[];$notice='';$post=null;$tagCsv='';if($schema['ready']&&$postId>0){$post=mg_blog_get_admin_post($pdo,$postId);if(!$post){http_response_code(404);$errors[]='Blog post not found.';$postId=0;}else{$tagCsv=implode(', ',mg_blog_tag_names($pdo,$postId));}}if($_SERVER['REQUEST_METHOD']==='POST'){if(!mg_verify_csrf((string)($_POST['csrf_token']??''))){$errors[]='Security token expired. Refresh and try again.';}elseif(!$schema['ready']){$errors[]='Blog SQL migration is required before saving posts.';}else{$saved=mg_blog_save_post($pdo,$_POST,$user,$errors);if($saved&&$errors===[]){header('Location: /admin/blog-editor.php?id='.$saved.'&saved=1',true,303);exit;}}}if(isset($_GET['saved'])){$notice='Post saved successfully.';}if($schema['ready']&&$postId>0){$post=mg_blog_get_admin_post($pdo,$postId);$tagCsv=$post?implode(', ',mg_blog_tag_names($pdo,$postId)):$tagCsv;}$categories=$schema['ready']?mg_blog_categories($pdo,false):[];$form=array_merge(['id'=>0,'title'=>'','slug'=>'','excerpt'=>'','body'=>'','featured_image'=>'','featured_image_alt'=>'','status'=>'draft','category_id'=>0,'seo_title'=>'','seo_description'=>'','canonical_url'=>'','cta_type'=>'none','is_featured'=>0,'published_at'=>''],is_array($post)?$post:[]);if($_SERVER['REQUEST_METHOD']==='POST'){$form=array_merge($form,$_POST);$tagCsv=(string)($_POST['tags']??$tagCsv);} $page_title=($postId>0?'Edit Blog Post':'Create Blog Post').' | Microgifter Admin';$page_section='account';$header_mode='account';$page_body_class='mg-admin-blog-page';$page_styles=['/assets/css/admin-shell.css','/assets/css/admin-blog.css','/assets/css/admin-blog-editor.css'];$page_scripts=['/assets/js/admin-blog-editor.js'];$adminActive='blog';require dirname(__DIR_