<section class="mg-app-shell mg-admin-app"><?php require dirname(__DIR__).'/includes/admin-sidebar.php'; ?><div class="mg-app-workspace mg-admin-workspace"><main class="mg-admin-blog-shell"><header class="mg-admin-blog-hero is-editor"><div><a class="mg-admin-blog-back" href="/admin/blog-posts.php">← Blog manager</a><span class="mg-eyebrow">Content Studio</span><h1><?= $postId>0?'Edit blog post':'Create blog post' ?></h1><p>Write Microgifter articles with SEO metadata, featured images, categories, tags, and sales-funnel CTA blocks.</p></div><div class="mg-admin-blog-actions"><?php if($postId>0): ?><a class="mg-btn mg-btn-soft" href="/admin/blog-preview.php?id=<?= $postId ?>" target="_blank" rel="noopener">Preview</a><?php endif; ?><a class="mg-btn mg-btn-ghost" href="/admin/blog-posts.php">All posts</a></div></header><?php if(!$schema['ready']): ?><section class="mg-admin-blog-alert"><strong>SQL migration required.</strong><span>Run <code>database/microgifter_blog_module.sql</code> before creating posts.</span></section><?php endif; ?><?php if($notice!==''): ?><section class="mg-admin-blog-alert is-success"><strong>Saved.</strong><span><?= mg_e($notice) ?></span></section><?php endif; ?><?php foreach($errors as $m): ?><section class="mg-admin-blog-alert is-error"><strong>Fix needed.</strong><span><?= mg_e((string)$m) ?></span></section><?php endforeach; ?><form class="mg-admin-blog-editor" method="post" action="/admin/blog-editor.php<?= $postId>0?'?id='.$postId:'' ?>" enctype="multipart/form-data" data-blog-editor-form><?= mg_csrf_field() ?><input type="hidden" name="id" value="<?= (int)$form['id'] ?>"><input type="hidden" name="featured_image" value="<?= mg_e((string)$form['featured_image']) ?>"><section class="mg-admin-blog-editor-main"><label class="mg-admin-blog-field is-title">Title<input type="text" name="title" maxlength="180" value="<?= mg_e((string)$form['title']) ?>" required></label><label class="mg-admin-blog-field">Slug<input type="text" name="slug" maxlength="190" value="<?= mg_e((string)$form['slug']) ?>"><small>Leave blank to generate automatically from the title.</small><span class="mg-admin-blog-slug-preview" data-blog-slug-preview>/blog-post.php?slug=post-slug</span></label><label class="mg-admin-blog-field">Excerpt<textarea name="excerpt" rows="4" maxlength="500"><?= mg_e((string)$form['excerpt']) ?></textarea></label><label class="mg-admin-blog-field is-body">Article body<textarea name="body" rows="22" required><?= mg_e((string)$form['body']) ?></textarea><small>Allowed HTML includes paragraphs, headings, links, lists, blockquotes, code, images, and basic formatting.</small></label><div class="mg-admin-blog-editor-tools" data-blog-editor-metrics><article><strong>0</strong><span>Words</span></article><article><strong>1</strong><span>Min read</span></article><article><strong>0/500</strong><span>Excerpt</span></article></div></section><aside class="mg-admin-blog-editor-side"><section class="mg-admin-blog-side-card"><h2>Publish controls</h2><label>Status<select name="status"><?php foreach(mg_blog_statuses() as $opt): ?><option value="<?= mg_e($opt) ?>" <?= (string)$form['status']===$opt?'selected':'' ?>><?= mg_e(ucfirst($opt)) ?></option><?php endforeach; ?></select></label><label>Publish date<input type="datetime-local" name="published_at" value="<?= mg_e(mg_blog_sql_to_datetime_input((string)($form['published_at']??''))) ?>"></label><label class="mg-admin-blog-check"><input type="checkbox" name="is_featured" value="1" <?= !empty($form['is_featured'])?'checked':'' ?>> Feature this post</label><div class="mg-admin-blog-save-row"><button class="mg-btn mg-btn-primary" type="submit">Save post</button><a class="mg-btn mg-btn-ghost" href="/admin/blog-posts.php">Cancel</a></div><div class="mg-admin-blog-secondary-save"><button type="button" data-blog-save-status="draft">Save Draft</button><button type="button" data-blog-save-status="published">Publish</button></div></section><section class="mg-admin-blog-side-card"><h2>Taxonomy</h2><label>Category<select name="category_id"><option value="0">Uncategorized</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (int)$form['category_id']===(int)$cat['id']?'selected':'' ?>><?= mg_e((string)$cat['name']) ?></option><?php endforeach; ?></select></label><label>Tags<input type="text" name="tags" value="<?= mg_e($tagCsv) ?>" placeholder="gifting, loyalty, hospitality"></label></section><section class="mg-admin-blog-side-card"><h2>Featured image</h2><?php if(!empty($form['featured_image'])): ?><div class="mg-admin-blog-image-preview" style="background-image:url('<?= mg_e((string)$form['featured_image']) ?>')"></div><?php endif; ?><label>Upload JPG, PNG, or WebP<input type="file" name="featured_image_file" accept="image/jpeg,image/png,image/webp"></label><label>Image URL/path<input type="text" name="featured_image" value="<?= mg_e((string)$form['featured_image']) ?>"></label><label>Alt text<input type="text" name="featured_image_alt" maxlength="255" value="<?= mg_e((string)$form['featured_image_alt']) ?>"></label></section><section class="mg-admin-blog-side-card"><h2>SEO</h2><label>SEO title<input type="text" name="seo_title" maxlength="180" value="<?= mg_e((string)$form['seo_title']) ?>"></label><label>SEO description<textarea name="seo_description" rows="4" maxlength="255"><?= mg_e((string)$form['seo_description']) ?></textarea></label><label>Canonical URL<input type="url" name="canonical_url" maxlength="255" value="<?= mg_e((string)$form['canonical_url']) ?>"></label><div class="mg-admin-blog-live-panel" data-blog-seo-preview><span>microgifter.com/blog-post.php?slug=post-slug</span><strong>SEO preview title</strong><p>SEO preview description.</p></div></section><section class="mg-admin-blog-side-card"><h2>CTA block</h2><label>Post CTA<select name="cta_type"><?php foreach(['none'=>'None','merchant_signup'=>'Merchant signup','investor_page'=>'Investor page','demo_request'=>'Demo request','campaign_builder